# plotgardener multi-panel genomic page (plotgardenerData example: IMR90 Hi-C + ChIP + gene track, hg19)
suppressPackageStartupMessages({library(plotgardener); library(plotgardenerData); library(TxDb.Hsapiens.UCSC.hg19.knownGene); library(org.Hs.eg.db)})
setwd(dirname(sub("--file=","",grep("--file=",commandArgs(FALSE),value=TRUE))))
data("IMR90_HiC_10kb"); data("IMR90_ChIP_H3K27ac_signal"); data("GM12878_ChIP_CTCF_signal"); data("IMR90_DNAloops_pairs")
png("v1_page_layout.png", 1500, 1300, res = 180)
pageCreate(width = 7.5, height = 6.5, default.units = "inches", showGuides = FALSE)
params <- pgParams(chrom = "chr21", chromstart = 28000000, chromend = 30300000, assembly = "hg19", x = .5, width = 6.5)
hic <- plotHicTriangle(data = IMR90_HiC_10kb, params = params, zrange = c(0, 70), resolution = 10000, y = .5, height = 2.5, just = c("left","top"), default.units = "inches")
annoHeatmapLegend(hic, x = 7, y = .5, width = .13, height = 1.2, just = c("right","top"))
plotPairsArches(data = IMR90_DNAloops_pairs, params = params, y = 3.1, height = .5, fill = "#1f4297", linecolor = "#1f4297", flip = TRUE)
plotSignal(data = IMR90_ChIP_H3K27ac_signal, params = params, y = 3.7, height = .6, fill = "#37a7db", linecolor = "#37a7db"); plotText("H3K27ac", x = .5, y = 3.7, just = c("left","top"), fontsize = 8)
plotSignal(data = GM12878_ChIP_CTCF_signal, params = params, y = 4.4, height = .6, fill = "#e0644e", linecolor = "#e0644e"); plotText("CTCF", x = .5, y = 4.4, just = c("left","top"), fontsize = 8)
plotGenes(params = params, y = 5.1, height = .7); plotGenomeLabel(chrom = "chr21", chromstart = 28000000, chromend = 30300000, assembly = "hg19", x = .5, y = 5.9, length = 6.5, scale = "Mb")
dev.off()
png("v2_gene_and_ideogram.png", 1500, 700, res = 180)
pageCreate(width = 7.5, height = 3.2, default.units = "inches", showGuides = FALSE)
plotIdeogram(chrom = "chr17", assembly = "hg19", x = .5, y = .3, width = 6.5, height = .3)
p2 <- pgParams(chrom = "chr17", chromstart = 43900000, chromend = 44400000, assembly = "hg19", x = .5, width = 6.5)  # MAPT locus (tauopathy)
plotGenes(params = p2, y = .9, height = 1.2, geneHighlights = data.frame(gene = "MAPT", color = "#c51b7d"), geneBackground = "grey60"); plotGenomeLabel(chrom = "chr17", chromstart = 43900000, chromend = 44400000, assembly = "hg19", x = .5, y = 2.3, length = 6.5, scale = "Kb")
plotText("MAPT locus (chr17q21.31)", x = .5, y = 2.8, just = "left", fontsize = 10)
dev.off()
